def Q(id, type, prompt, answer, explanation, sources, section, spot=None, difficulty=2, **kw):
    d = {"id": id, "type": type, "prompt": prompt, "answer": answer, "explanation": explanation, "source_ids": sources,
         "section_id": section, "spotlight_id": spot, "difficulty": difficulty}
    d.update(kw)
    return d

